<script setup lang="ts">
import {computed,onUnmounted,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import type {ConnectionsConfig,ConnectionsResult} from '../tools/m4'
const props=defineProps<{en:boolean;config:ConnectionsConfig}>()
const result=ref<ConnectionsResult|null>(null),error=ref(''),busy=ref(false),auto=ref(false),page=ref(0)
const rows=computed(()=>result.value?.rows.slice(page.value*50,page.value*50+50)??[])
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{result.value=await invoke('query_connections',{config:{...props.config}});page.value=0}catch(e){error.value=String(e)}finally{busy.value=false}}
const timer=setInterval(()=>{if(auto.value)refresh()},2000);onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel connections-tool m4-results"><h2>{{en?'Local Ports & Connections':'本机端口与连接'}}</h2>
 <form @submit.prevent="refresh" class="connections-filters"><label>{{en?'Protocol':'协议'}}<select id="connections-protocol" v-model="config.protocol"><option value="">All</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>{{en?'Family':'地址族'}}<select v-model="config.family"><option value="auto">Auto</option><option value="ipv4">IPv4</option><option value="ipv6">IPv6</option></select></label><label>{{en?'Port':'端口'}}<input id="connections-port" :value="config.port??''" @input="config.port=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null" type="number" min="1" max="65535"></label><label>PID<input :value="config.pid??''" @input="config.pid=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null" type="number" min="1"></label><label>{{en?'State':'状态'}}<input v-model="config.state" placeholder="listen / established"></label><label>{{en?'Address contains':'地址包含'}}<input v-model="config.address"></label><label>{{en?'Process contains':'进程名包含'}}<input v-model="config.process"></label><label class="check"><input v-model="config.listening" type="checkbox">{{en?'TCP listeners / UDP endpoints':'TCP 监听 / UDP 端点'}}</label><button class="primary" :disabled="busy">{{busy?(en?'Querying…':'查询中…'):(en?'Refresh':'刷新')}}</button><label class="check"><input v-model="auto" type="checkbox">{{en?'Refresh every 2s':'每 2 秒刷新'}}</label></form>
 <p class="error" role="alert" v-if="error">{{error}}</p>
 <p>{{en?'Read-only. UDP has no TCP state. Permission limits and process exit can hide names or endpoints.':'只读查询；UDP 无 TCP 状态，权限限制或进程退出可能使名称与端点不可见。'}}</p>
 <template v-if="result"><p>{{result.adapter}} · {{result.query_started_at}} → {{result.query_ended_at}} · {{result.duration_ms}} ms</p><p v-if="result.partial" class="info-note">{{en?'Partial visibility':'部分可见'}} · {{result.process_visibility}}</p><p class="error" v-for="e in result.partial_errors" :key="e.code+e.message">{{e.code}} · {{e.message}}</p>
 <div class="m4-table"><table><thead><tr><th>{{en?'Protocol':'协议'}}</th><th>{{en?'Local':'本机'}}</th><th>{{en?'Remote':'远端'}}</th><th>{{en?'State':'状态'}}</th><th>PID</th><th>{{en?'Process':'进程'}}</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r.protocol}} / {{r.family}}</td><td>{{r.local_endpoint}}</td><td>{{r.remote_endpoint??'—'}}</td><td>{{r.state??'—'}}</td><td>{{r.pid??'?'}}</td><td>{{r.process??(en?'Unknown':'未知')}}</td></tr></tbody></table></div><p v-if="!result.rows.length">{{en?'No visible endpoints match these filters.':'没有匹配筛选条件的可见端点。'}}</p><button :disabled="page===0" @click="page--">←</button> {{page+1}} / {{Math.max(1,Math.ceil(result.rows.length/50))}} · {{result.rows.length}} <button :disabled="(page+1)*50>=result.rows.length" @click="page++">→</button></template>
</section></template>
